      lbl(S, 'l1', 19.0, 1.7, ['웹 서버와 프레임워크 사이의 약속 · WSGI는 요청 하나에 함수 호출 하나, 끝날 때까지 워커를 붙잡아요', 'the server–framework contract: WSGI makes one call per request and holds the worker'], 'a', 1, { w: 12.4 });
