      lbl(S, 'l4', 19.0, 8.8, ['같은 서버의 DB인데도 101번이면 수십 ms · 네트워크 지연은 쿼리 수만큼 곱해져요', '101 queries cost tens of ms even locally, plus network latency per query'], 'w', 4, { w: 12.4 });
