    hl: [[0, 2, 'danger'], [2, 1, 'ok'], [3, 1, 'ok'], [4, 1, 'danger']],
    draw: (S) => {
      cells(S, 'ca', 19.0, .5, [['A read 5', 'accent'], ['A write 6', 'accent']], 1, { dx: 5.0, w: 4.6, h: .85 });
      cells(S, 'cb', 21.5, 1.5, [['B read 5', 'warn'], ['B write 6', 'warn']], 1, { dx: 5.0, w: 4.6, h: .85 });
      lbl(S, 'l1', 19.0, 2.65, ['두 요청이 같은 값 5를 읽고 각자 6을 쓰면 증가 한 번이 사라져요(갱신 손실)', 'two requests read 5 and both write 6, so one increment is lost (a lost update)'], 'r', 1, { w: 12.4 });
      rbars(S, 'b2', 4.0, [['read+save', .85, 'danger', '170 / 1000']], 2);
      lbl(S, 'l2', 19.0, 4.7, ['스레드 10개가 100번씩 늘리자 1,000이어야 할 재고가 170 · 830번이 사라졌어요', '10 threads adding 100 each should reach 1,000; the stock ended at 170'], 'r', 2, { w: 12.4 });
      rbars(S, 'b3', 6.1, [['F() update', 5.0, 'ok', '1000 · 0.53 s']], 3);
      lbl(S, 'l3', 19.0, 6.8, ["F('stock') + 1은 계산을 SQL로 보내 DB가 한 문장 안에서 처리해요 · 정확히 1,000", "F('stock') + 1 moves the math into SQL, done atomically: exactly 1,000"], 'g', 3, { w: 12.4 });
      rbars(S, 'b4', 8.2, [['for_update', 5.0, 'ok', '1000 · 1.9 s']], 4);
      lbl(S, 'l4', 19.0, 8.9, ['읽은 값으로 판단해야 하면 select_for_update로 행을 잠가요 · 정확하지만 3.5배 느렸어요', 'when logic needs the value, lock the row with select_for_update: correct, 3.5× slower'], 'g', 4, { w: 12.4 });
      lbl(S, 'm1', 1, 7.0, ['save()는 모든 필드를 덮어써요 · 다른 요청이 바꾼 필드도 사라질 수 있어 update_fields를 줘요', 'save() rewrites every field, which can erase others’ changes; pass update_fields'], 'w', 2, { w: 16.0 });
    },
    notes: [['p = Product.objects.get(); p.stock += 1; p.save()는 값을 파이썬으로 읽어 와 바꾼 뒤 다시 써요 · 두 요청이 거의 동시에 같은 값 5를 읽으면 둘 다 6을 쓰고, 한 번의 증가가 사라져요 · 이것을 갱신 손실이라고 해요', 'p = Product.objects.get(); p.stock += 1; p.save() reads the value into Python, changes it and writes it back, so when two requests read the same value 5 at nearly the same time, both write 6 and one increment disappears, which is called a lost update'], ['PostgreSQL에서 스레드 10개가 각자 100번씩 이 코드로 재고를 늘렸어요 · 1,000이 되어야 할 재고가 두 번의 실행에서 170과 176이었어요 · 800번이 넘는 증가가 사라졌고, 오류는 하나도 나지 않았어요', 'on PostgreSQL, 10 threads each increased the stock 100 times with this code, and the stock that should have reached 1,000 ended at 170 and 176 in two runs, over 800 increments lost without a single error'], ['F(\'stock\') + 1은 값을 파이썬으로 가져오지 않고 UPDATE … SET stock = stock + 1이라는 SQL로 보내요 · DB가 문장 하나 안에서 원자적으로 처리하므로 같은 실험에서 정확히 1,000이 됐고 시간도 0.53초로 가장 짧았어요', 'F(\'stock\') + 1 does not bring the value into Python but sends SQL of the form UPDATE … SET stock = stock + 1, processed atomically by the database within one statement, so the same experiment reached exactly 1,000 and was also fastest at 0.53 s'], ['재고가 충분한지 확인하는 것처럼 읽은 값으로 판단해야 한다면, transaction.atomic() 안에서 select_for_update()로 행을 잠그고 읽어요 · 정확히 1,000이었지만 요청들이 잠금을 기다려 1.9초로 약 3.5배 느렸어요 · save()에는 update_fields를 줘서 바꾼 필드만 쓰게 해요', 'when logic depends on the value read, such as checking that stock suffices, the row is locked and read with select_for_update() inside transaction.atomic(), which gave exactly 1,000 but took 1.9 s, about 3.5 times slower, as requests waited for the lock, while save() is given update_fields so it writes only the fields that changed']],
