      lbl(S, 'l3', 19.0, 7.3, ['안쪽 atomic은 세이브포인트예요 · 안쪽만 되돌리고 바깥 주문 1건은 커밋됐어요', 'an inner atomic is a savepoint: only it rolled back, and the outer order committed'], 'a', 3, { w: 12.4 });
      lbl(S, 'l4', 19.0, 8.8, ['메일처럼 되돌릴 수 없는 일은 on_commit으로 · 롤백되자 아예 실행되지 않았어요', 'irreversible work like email goes in on_commit; after a rollback it never ran'], 'g', 4, { w: 12.4 });
