function sAsyncBlock() {
  return CW('pyweb-asyncblock', {
    code: [['async def a(): time.sleep(0.5)  # 루프 멈춤', 'async def a(): time.sleep(0.5)  # blocks loop'], 'async def b(): await asyncio.sleep(0.5)', ['def c(): time.sleep(0.5)    # 스레드 풀로', 'def c(): time.sleep(0.5)    # thread pool'], ['# 동시 10개: a 5.0초 · b 0.54초 · c 0.56초', '# 10 at once: a 5.0 s · b 0.54 s · c 0.56 s'], ['# a가 도는 동안 /hello가 1.9초', '# /hello took 1.9 s while a ran']],
    hl: [[0, 1, 'danger'], [1, 1, 'ok'], [2, 1, 'ok'], [3, 2, 'accent']],
    draw: (S) => {
      rbars(S, 'b1', .5, [['async+sleep', 5.0, 'danger', '5.0 s']], 1);
      lbl(S, 'l1', 19.0, 1.2, ['async def 안에서 time.sleep을 부르자 요청 10개가 하나씩 처리돼 5초 · 이벤트 루프가 멈췄어요', 'time.sleep inside async def made 10 requests run one by one: 5 s, loop frozen'], 'r', 1, { w: 12.4 });
      rbars(S, 'b2', 2.7, [['await sleep', .54, 'ok', '0.54 s']], 2);
      lbl(S, 'l2', 19.0, 3.4, ['await asyncio.sleep은 기다리는 동안 루프를 돌려줘서 10개가 함께 0.54초', 'await asyncio.sleep yields the loop while waiting: all 10 done in 0.54 s'], 'g', 2, { w: 12.4 });
      rbars(S, 'b3', 4.9, [['def + sleep', .56, 'ok', '0.56 s']], 3);
      lbl(S, 'l3', 19.0, 5.6, ['async가 없는 def는 FastAPI가 스레드 풀에서 돌려서 블로킹 코드도 0.56초', 'a plain def runs in FastAPI’s thread pool, so even blocking code took 0.56 s'], 'g', 3, { w: 12.4 });
      T(S, 't4', 19.0, 7.1, '/hello during 4 blocking calls → 1.9 s', 'cz-mono dfx-tiny dfx-r', 4, { w: 12.4 });
      lbl(S, 'l4', 19.0, 7.7, ['막힌 루프는 다른 모든 요청을 세워요 · 1ms짜리 /hello가 1.9초를 기다렸어요', 'a blocked loop stalls everything: a 1 ms /hello waited 1.9 s'], 'r', 4, { w: 12.4 });
      lbl(S, 'm1', 1, 7.0, ['async def 안에서는 await할 수 있는 라이브러리만 · requests 대신 httpx, psycopg는 async 연결로', 'inside async def use awaitable libraries: httpx instead of requests, async psycopg'], 'w', 1, { w: 16.0 });
    },
    notes: [['FastAPI에서 async def 엔드포인트는 이벤트 루프 위에서 직접 실행돼요 · 그 안에서 time.sleep(0.5)처럼 기다리는 동기 함수를 부르면 루프 전체가 그동안 멈춰요 · 요청 10개를 동시에 보내자 하나씩 차례로 처리되어 5.0초가 걸렸어요', 'in FastAPI an async def endpoint runs directly on the event loop, so calling a synchronous waiting function such as time.sleep(0.5) inside it stops the whole loop meanwhile, and 10 concurrent requests were handled one after another, taking 5.0 s'], ['같은 대기를 await asyncio.sleep(0.5)로 바꾸자 10개가 함께 0.54초에 끝났어요 · await는 기다리는 동안 루프에게 제어를 돌려줘서 다른 요청을 진행하게 해요 · 네트워크와 DB 호출도 await할 수 있는 라이브러리를 써야 같은 효과가 나요', 'replacing the wait with await asyncio.sleep(0.5) finished all 10 together in 0.54 s, since await hands control back to the loop while waiting so other requests progress, and network and database calls give the same effect only through libraries that can be awaited'], ['async를 빼고 일반 def로 쓴 엔드포인트는 FastAPI가 스레드 풀에서 실행해요 · 그래서 time.sleep(0.5)를 그대로 써도 10개가 0.56초에 끝났어요 · 동기 라이브러리를 써야 한다면 async def보다 def가 안전한 선택이에요', 'an endpoint written as a plain def without async is run by FastAPI in a thread pool, so even with time.sleep(0.5) as is, all 10 finished in 0.56 s, which makes def the safer choice over async def when synchronous libraries must be used'], ['막힌 루프의 피해는 그 엔드포인트에서 끝나지 않아요 · 블로킹 요청 4개가 도는 중에 보낸, 1ms면 끝나는 /hello가 1.9초를 기다렸어요 · async def 안에서는 requests 대신 httpx.AsyncClient, 동기 DB 드라이버 대신 async 드라이버를 써요', 'the damage of a blocked loop does not stay in that endpoint: a /hello that normally takes 1 ms, sent while 4 blocking requests were running, waited 1.9 s, so inside async def, httpx.AsyncClient replaces requests and async drivers replace synchronous database drivers']],
    fin: [['async 안의 블로킹은 루프를 멈춰요', 'blocking inside async freezes the loop', 'dfx-xs dfx-a'], ['기다릴 땐 await', 'await when waiting'], ['동기 코드라면 def로', 'use def for synchronous code']],
    caps: [['멈춘 이벤트 루프', 'A frozen event loop'], ['await로 기다리기', 'Waiting with await'], ['def와 스레드 풀', 'def and the thread pool'], ['다른 요청의 피해', 'Collateral damage'], ['async 안의 블로킹', 'Blocking inside async']]
  });
}

