      lbl(S, 'l2', 19.0, 4.3, ['def 엔드포인트와 def 의존성은 모두 하나의 스레드 풀을 나눠 써요 · 기본 한도가 40', 'def endpoints and def dependencies share one thread pool, capped at 40 by default'], 'a', 2, { w: 12.4 });
      T(S, 't3', 19.0, 5.7, '41st request → waits for a free thread', 'cz-mono dfx-tiny dfx-w', 3, { w: 12.4 });
